def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1
    result += current_char + str(count)
    return result

